from collections import defaultdict
from sys import maxsize

class Solution:

	def dfs(self, node, visited, adj, diameter, last_node):
		visited[node] = 1
		for (nbr, d) in adj[node]:
			if visited[nbr] == -1:
				diameter[0] = min(diameter[0], d)
				last_node[0] = nbr
				self.dfs(nbr, visited, adj, diameter, last_node)

	def solve(self, n, p, a, b, d):
		adj = defaultdict(list)
		indeg = defaultdict(int)
		for i in range(p):
			adj[a[i]].append((b[i], d[i]))
			indeg[b[i]] += 1
		visited = [-1] * (n + 1)
		ans = []
		for i in range(1, n + 1):
			if visited[i] == -1 and indeg[i] == 0:
				diameter = [maxsize]
				last_node = [i]
				self.dfs(i, visited, adj, diameter, last_node)
				if i != last_node[0]:
					ans.append([i, last_node[0], diameter[0]])
		ans.sort(key=lambda x: x[0])
		return ans
